import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetLookupServlet.class.getName());
    private static final String DB_URL = "jdbc:postgresql://db-internal:5432/assets";
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetTag = req.getParameter("tag");
        String department = req.getParameter("dept");

        if (assetTag == null || assetTag.isEmpty()) {
            resp.sendError(400, "Missing tag parameter");
            return;
        }

        // Validate department is alphanumeric
        if (department != null && !department.matches("[a-zA-Z0-9_]+")) {
            resp.sendError(400, "Invalid department format");
            return;
        }

        // Build query - tag is used in LIKE clause for flexible matching
        String query = "SELECT asset_id, description, location, assigned_to, status " +
                       "FROM inventory WHERE asset_tag LIKE '%" + assetTag + "%'";

        if (department != null) {
            query += " AND department = '" + department + "'";
        }

        log.info("Asset lookup query for tag: " + assetTag.substring(0, Math.min(assetTag.length(), 20)));

        resp.setContentType("application/json");
        resp.setCharacterEncoding("UTF-8");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            int count = 0;

            while (rs.next() && count < 100) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"asset_id\": \"").append(escapeJson(rs.getString("asset_id"))).append("\",");
                json.append("\"description\": \"").append(escapeJson(rs.getString("description"))).append("\",");
                json.append("\"location\": \"").append(escapeJson(rs.getString("location"))).append("\",");
                json.append("\"assigned_to\": \"").append(escapeJson(rs.getString("assigned_to"))).append("\",");
                json.append("\"status\": \"").append(escapeJson(rs.getString("status"))).append("\"");
                json.append("}");
                first = false;
                count++;
            }

            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }

    // Health check endpoint
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
